mapper.select:
select

from platform_audit_log

  and occurred_at >= #{from,jdbcType=TIMESTAMP}
  and occurred_at < #{to,jdbcType=TIMESTAMP}
  and actor_username = #{actorUsername,jdbcType=VARCHAR}
  and cluster_id = #{clusterId,jdbcType=VARCHAR}
  and `namespace` = #{namespace,jdbcType=VARCHAR}
  and `result` = #{result,jdbcType=VARCHAR}
  and `action` = #{action,jdbcType=VARCHAR}

    and (occurred_at < #{cursorOccurredAt,jdbcType=TIMESTAMP}
         or (occurred_at = #{cursorOccurredAt,jdbcType=TIMESTAMP} and id < #{cursorId,jdbcType=BIGINT}))


order by occurred_at desc, id desc
limit #{limit,jdbcType=INTEGER}

mapper.delete:
delete from platform_audit_log

  and occurred_at >= #{from,jdbcType=TIMESTAMP}
  and occurred_at < #{to,jdbcType=TIMESTAMP}
